-- Same problem is solved in SQL; C++ equivalent shown for reference.
#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<pair<string,double>> combos(vector<string>& names, vector<double>& costs) {
        int n = names.size();
        vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a,int b){return names[a]<names[b];});
        vector<pair<string,double>> res;
        for (int i=0;i<n;i++) for (int j=i+1;j<n;j++) for (int k=j+1;k<n;k++) {
            int a=idx[i],b=idx[j],c=idx[k];
            string p = names[a]+","+names[b]+","+names[c];
            double s = round((costs[a]+costs[b]+costs[c])*100)/100;
            res.push_back({p,s});
        }
        sort(res.begin(),res.end(),[](auto&x,auto&y){
            if(x.second!=y.second) return x.second>y.second; return x.first<y.first;});
        return res;
    }
};

