// Java equivalent (reference)
import java.util.*;
class Solution {
    public List<Object[]> combos(String[] names, double[] costs) {
        Integer[] idx = new Integer[names.length];
        for (int i=0;i<idx.length;i++) idx[i]=i;
        Arrays.sort(idx,(a,b)->names[a].compareTo(names[b]));
        List<Object[]> res = new ArrayList<>();
        int n=names.length;
        for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)for(int k=j+1;k<n;k++){
            int a=idx[i],b=idx[j],c=idx[k];
            String p=names[a]+","+names[b]+","+names[c];
            double s=Math.round((costs[a]+costs[b]+costs[c])*100)/100.0;
            res.add(new Object[]{p,s});
        }
        res.sort((x,y)->{int c=Double.compare((double)y[1],(double)x[1]);
            return c!=0?c:((String)x[0]).compareTo((String)y[0]);});
        return res;
    }
}

