// JavaScript equivalent (reference)
var solve = function(names, costs) {
    const idx = names.map((_, i) => i).sort((a, b) => names[a] < names[b] ? -1 : 1);
    const res = [];
    const n = names.length;
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) for (let k = j + 1; k < n; k++) {
        const [a, b, c] = [idx[i], idx[j], idx[k]];
        res.push([names[a]+','+names[b]+','+names[c],
                  Math.round((costs[a]+costs[b]+costs[c])*100)/100]);
    }
    res.sort((x, y) => y[1] - x[1] || (x[0] < y[0] ? -1 : 1));
    return res;
};
